#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <functional>
using namespace std;

class Table {
    vector<map<string,string>> rows;
public:
    void insert(const map<string,string>& row) { rows.push_back(row); }

    void select(function<bool(const map<string,string>&)> pred) {
        for (auto& row : rows) {
            if (pred(row)) {
                for (auto& [key, val] : row) cout << key << ":" << val << " ";
                cout << endl;
            }
        }
    }

    void selectAll() {
        for (auto& row : rows) {
            for (auto& [key, val] : row) cout << key << ":" << val << " ";
            cout << endl;
        }
    }
};

int main() {
    Table users;
    users.insert({{"name","Alice"}, {"age","25"}});
    users.insert({{"name","Bob"}, {"age","17"}});
    users.insert({{"name","Charlie"}, {"age","30"}});
    cout << "All users:" << endl;
    users.selectAll();
    cout << "Age > 18:" << endl;
    users.select([](const auto& row) { return stoi(row.at("age")) > 18; });
    return 0;
}
